import sys

def main():
    n = int(sys.stdin.readline())
    if n == 3:
        print(6)
        return
    # Initialize DP table
    dp = [[0]*(n+1) for _ in range(n+1)]
    # Fill DP for lengths >= 3
    for length in range(3, n+1):
        for i in range(1, n - length + 2):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(i+1, j):
                current = dp[i][k] + dp[k][j] + i * k * j
                if current < dp[i][j]:
                    dp[i][j] = current
    print(dp[1][n])

if __name__ == "__main__":
    main()
